<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu-like Desktop</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            font-family: 'Ubuntu', 'Segoe UI', 'Cantarell', sans-serif;
        }
        body {
            overflow: hidden;
            background: #2d0922; /* fallback */
        }
        #desktop {
            position: relative;
            width: 100vw;
            height: 100vh;
            background: #2b0e1e; /* deep purple-black */
            background-image: radial-gradient(circle at 30% 40%, #3e1a2f 0%, #1a0a12 90%);
            overflow: hidden;
            user-select: none;
        }
        /* Taskbar */
        #taskbar {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 56px;
            background: rgba(30, 15, 20, 0.85);
            backdrop-filter: blur(8px);
            border-top: 1px solid #6a3e4a;
            display: flex;
            align-items: center;
            padding: 0 20px;
            gap: 16px;
            z-index: 100;
            box-shadow: 0 -2px 12px rgba(0,0,0,0.6);
        }
        #taskbar button {
            background: rgba(80, 40, 55, 0.6);
            border: 1px solid #8f5c6a;
            color: #f0e6e8;
            padding: 8px 18px;
            border-radius: 6px;
            font-size: 14px;
            cursor: pointer;
            transition: all 0.2s;
            font-weight: 500;
            letter-spacing: 0.3px;
            backdrop-filter: blur(4px);
            box-shadow: 0 2px 6px rgba(0,0,0,0.5);
        }
        #taskbar button:hover {
            background: rgba(130, 70, 90, 0.7);
            border-color: #b5828e;
            transform: scale(1.02);
        }
        #taskbar button:active {
            transform: scale(0.96);
        }

        /* Windows */
        .window {
            position: absolute;
            background: #2a1a22;
            border: 1px solid #6f4a58;
            border-radius: 10px 10px 6px 6px;
            box-shadow: 0 16px 40px rgba(0,0,0,0.7);
            min-width: 360px;
            min-height: 280px;
            backdrop-filter: blur(2px);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            resize: both;
            transition: opacity 0.15s;
        }
        .window-header {
            background: #3a232e;
            padding: 8px 12px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 1px solid #684a55;
            cursor: default;
        }
        .window-header span {
            color: #f0e0e6;
            font-weight: 600;
            font-size: 14px;
        }
        .win-close {
            background: #9f4a5a;
            border: none;
            color: white;
            font-weight: bold;
            font-size: 16px;
            width: 28px;
            height: 28px;
            border-radius: 50%;
            cursor: pointer;
            transition: 0.15s;
            line-height: 28px;
            text-align: center;
            padding: 0;
        }
        .win-close:hover {
            background: #c25a6e;
            transform: scale(1.1);
        }
        .window-body {
            flex: 1;
            overflow: auto;
            padding: 10px 12px;
            background: #1f131a;
            color: #ebdfe3;
        }

        /* Files app */
        #files-window {
            width: 540px;
            height: 380px;
            top: 6%;
            left: 5%;
        }
        #files-header {
            display: flex;
            align-items: center;
            gap: 8px;
            background: #2c1a23;
            padding: 6px 8px;
            border-bottom: 1px solid #4d3340;
            flex-wrap: wrap;
        }
        #files-path {
            background: #130a10;
            padding: 4px 12px;
            border-radius: 14px;
            color: #dacfd4;
            font-size: 13px;
            flex: 1;
            border: 1px solid #4d3540;
            min-width: 120px;
        }
        #files-up {
            background: #3e2a34;
            border: 1px solid #6c4e5a;
            color: #f0e2e8;
            font-size: 16px;
            padding: 2px 12px;
            border-radius: 20px;
            cursor: pointer;
            font-weight: bold;
            transition: 0.1s;
        }
        #files-up:hover { background: #5a3f4b; }
        .fs-item {
            padding: 6px 10px;
            margin: 3px 0;
            background: #2a1d24;
            border-radius: 6px;
            cursor: pointer;
            list-style: none;
            border: 1px solid transparent;
            font-size: 14px;
            transition: 0.08s;
        }
        .fs-item:hover {
            background: #3f2b35;
            border-color: #7b5a68;
            padding-left: 14px;
        }

        /* Notepad */
        #notepad-window {
            width: 520px;
            height: 380px;
            top: 10%;
            left: 30%;
        }
        #tabs {
            display: flex;
            gap: 4px;
            background: #24171e;
            padding: 6px 8px;
            flex-wrap: wrap;
            border-bottom: 1px solid #4f3743;
            align-items: center;
        }
        .tab {
            background: #3d2a34;
            border: 1px solid #604652;
            color: #dacfd6;
            padding: 4px 16px;
            border-radius: 20px;
            font-size: 13px;
            cursor: pointer;
            transition: 0.1s;
        }
        .tab.active {
            background: #755565;
            border-color: #b28696;
            color: white;
            font-weight: 500;
        }
        .tab:hover { background: #57404b; }
        #new-tab {
            background: #3b2832;
            border: 1px solid #6a4f5a;
            color: #eddce3;
            padding: 4px 12px;
            border-radius: 20px;
            cursor: pointer;
            font-weight: bold;
            font-size: 18px;
            margin-left: auto;
        }
        #new-tab:hover { background: #5a414d; }
        #editor {
            width: 100%;
            flex: 1;
            background: #1a1016;
            color: #f0e6ea;
            border: none;
            padding: 14px 16px;
            font-size: 14px;
            font-family: 'Cascadia Code', 'Fira Code', monospace;
            resize: none;
            outline: none;
            line-height: 1.5;
            min-height: 180px;
        }
        #editor::placeholder {
            color: #6f5b64;
        }

        /* responsive tweaks */
        @media (max-width: 700px) {
            .window { min-width: 300px; left: 2% !important; top: 4% !important; width: 96% !important; }
        }
    </style>
</head>
<body>
<div id="desktop">
    <!-- Taskbar -->
    <div id="taskbar">
        <button id="open-files">📁 Files</button>
        <button id="open-notepad">📝 Notepad</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window" style="display:none;">
        <div class="window-header">
            <span>📂 Files</span>
            <button class="win-close" data-window="files-window">✕</button>
        </div>
        <div id="files-header">
            <span id="files-path">/</span>
            <button id="files-up" title="parent directory">⬆</button>
        </div>
        <div id="files-listing" class="window-body" style="padding-top:6px;"></div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window" style="display:none;">
        <div class="window-header">
            <span>📄 Notepad</span>
            <button class="win-close" data-window="notepad-window">✕</button>
        </div>
        <div id="tabs"></div>
        <textarea id="editor" placeholder="Start typing..."></textarea>
    </div>
</div>
<script>
    (function() {
        // ----- FILESYSTEM (static fake) -----
        const fs = {
            '/': ['bin', 'etc', 'home', 'usr', 'var'],
            '/bin': ['bash', 'ls', 'grep'],
            '/etc': ['hosts', 'passwd', 'fstab'],
            '/usr': ['lib', 'share', 'local'],
            '/var': ['log', 'cache', 'tmp'],
            '/home': ['user'],
            '/home/user': ['Documents', 'Downloads', 'Pictures', '.bashrc', 'todo.txt'],
            '/home/user/Documents': ['resume.pdf', 'notes.txt', 'project'],
            '/home/user/Downloads': ['ubuntu-24.04.iso', 'photo.jpg'],
            '/home/user/Pictures': ['wallpaper.png', 'screenshot.jpg', 'vacation']
        };
        // add deeper
        fs['/home/user/Documents/project'] = ['src', 'README.md'];
        fs['/home/user/Pictures/vacation'] = ['beach.jpg', 'sunset.png'];

        // state
        let currentPath = '/';
        const filesListing = document.getElementById('files-listing');
        const filesPath = document.getElementById('files-path');

        function renderDirectory(path) {
            const entries = fs[path];
            if (!entries) {
                // fallback empty
                filesListing.innerHTML = '<div style="color:#a08a94;">(empty directory)</div>';
                return;
            }
            let html = '';
            for (const name of entries) {
                const full = path === '/' ? '/' + name : path + '/' + name;
                const isFolder = fs[full] !== undefined;
                const icon = isFolder ? '📁' : '📄';
                html += `<div class="fs-item" data-path="${full}" data-folder="${isFolder}">${icon} ${name}</div>`;
            }
            filesListing.innerHTML = html || '<div style="color:#a08a94;">(empty)</div>';
            filesPath.textContent = path;
            currentPath = path;
        }

        // navigation
        filesListing.addEventListener('dblclick', (e) => {
            const item = e.target.closest('.fs-item');
            if (!item) return;
            const isFolder = item.dataset.folder === 'true';
            if (!isFolder) return;
            const path = item.dataset.path;
            if (fs[path] !== undefined) {
                renderDirectory(path);
            }
        });

        document.getElementById('files-up').addEventListener('click', () => {
            if (currentPath === '/') return;
            const parent = currentPath.substring(0, currentPath.lastIndexOf('/'));
            const resolved = parent === '' ? '/' : parent;
            if (fs[resolved] !== undefined) {
                renderDirectory(resolved);
            } else {
                // fallback to root
                renderDirectory('/');
            }
        });

        // initial render
        renderDirectory('/');

        // ----- window open/close -----
        const desktop = document.getElementById('desktop');
        const filesWin = document.getElementById('files-window');
        const notepadWin = document.getElementById('notepad-window');

        document.getElementById('open-files').addEventListener('click', () => {
            filesWin.style.display = 'flex';
            filesWin.style.zIndex = Date.now() % 1000 + 10;
            // ensure not collapsed
            if (filesWin.offsetWidth < 360) filesWin.style.width = '540px';
            if (filesWin.offsetHeight < 240) filesWin.style.height = '380px';
        });

        document.getElementById('open-notepad').addEventListener('click', () => {
            notepadWin.style.display = 'flex';
            notepadWin.style.zIndex = Date.now() % 1000 + 10;
            if (notepadWin.offsetWidth < 360) notepadWin.style.width = '520px';
            if (notepadWin.offsetHeight < 240) notepadWin.style.height = '380px';
        });

        // close buttons (delegation)
        document.addEventListener('click', (e) => {
            const closeBtn = e.target.closest('.win-close');
            if (!closeBtn) return;
            const winId = closeBtn.dataset.window;
            if (winId) {
                const win = document.getElementById(winId);
                if (win) win.style.display = 'none';
            }
        });

        // ----- NOTEPAD with localStorage persistence -----
        const tabsContainer = document.getElementById('tabs');
        const editor = document.getElementById('editor');
        const newTabBtn = document.getElementById('new-tab');

        // data
        let tabs = []; // [{id, content}]
        let activeTabId = null;

        // storage key
        const STORAGE_KEY = 'notepad_tabs';

        // load from localStorage
        function loadFromStorage() {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
                try {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed) && parsed.length) {
                        tabs = parsed;
                        // ensure content string
                        tabs = tabs.map(t => ({ id: t.id || Date.now() + Math.random(), content: t.content || '' }));
                        return true;
                    }
                } catch (e) {}
            }
            return false;
        }

        function saveToStorage() {
            const data = tabs.map(t => ({ id: t.id, content: t.content }));
            localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        }

        // init tabs: if no stored data, create one default tab
        function initTabs() {
            if (!loadFromStorage() || tabs.length === 0) {
                tabs = [{ id: 'tab_' + Date.now(), content: '' }];
            }
            // set active to first
            activeTabId = tabs[0].id;
            renderTabs();
            updateEditor();
            saveToStorage();
        }

        function renderTabs() {
            tabsContainer.innerHTML = '';
            for (const tab of tabs) {
                const tabEl = document.createElement('span');
                tabEl.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
                tabEl.dataset.tabId = tab.id;
                const shortLabel = '📄 ' + (tab.content.trim() ? tab.content.split('\n')[0].substring(0, 16) || 'untitled' : 'untitled');
                tabEl.textContent = shortLabel;
                tabEl.title = 'Click to switch';
                tabsContainer.appendChild(tabEl);
            }
            // add new-tab button at the end
            const newBtn = document.getElementById('new-tab');
            if (newBtn) tabsContainer.appendChild(newBtn);
        }

        function updateEditor() {
            const active = tabs.find(t => t.id === activeTabId);
            if (active) {
                editor.value = active.content;
            } else {
                editor.value = '';
            }
        }

        // switch tab on click (delegation)
        tabsContainer.addEventListener('click', (e) => {
            const tabEl = e.target.closest('.tab');
            if (!tabEl) return;
            const id = tabEl.dataset.tabId;
            if (id && tabs.some(t => t.id === id)) {
                activeTabId = id;
                renderTabs();
                updateEditor();
                // save but not content change yet
            }
        });

        // new tab
        newTabBtn.addEventListener('click', () => {
            const newTab = { id: 'tab_' + Date.now() + Math.random(), content: '' };
            tabs.push(newTab);
            activeTabId = newTab.id;
            renderTabs();
            updateEditor();
            saveToStorage();
            editor.focus();
        });

        // editor change -> update active tab and persist
        editor.addEventListener('input', () => {
            const active = tabs.find(t => t.id === activeTabId);
            if (active) {
                active.content = editor.value;
                // update tab label (debounced? just update on input)
                saveToStorage();
                // refresh tab labels to show first line
                renderTabs(); 
                // but preserve active class (renderTabs reuses active)
            }
        });

        // also update when switching away? input handles it.

        // extra: make windows draggable (polish)
        function makeDraggable(win) {
            const header = win.querySelector('.window-header');
            let offsetX, offsetY, mouseX, mouseY, dragging = false;

            header.addEventListener('mousedown', (e) => {
                if (e.target.closest('.win-close')) return;
                dragging = true;
                const rect = win.getBoundingClientRect();
                offsetX = e.clientX - rect.left;
                offsetY = e.clientY - rect.top;
                win.style.cursor = 'grabbing';
                win.style.zIndex = Date.now() % 1000 + 10;
            });

            document.addEventListener('mousemove', (e) => {
                if (!dragging) return;
                e.preventDefault();
                let nx = e.clientX - offsetX;
                let ny = e.clientY - offsetY;
                // clamp to viewport
                nx = Math.max(0, Math.min(window.innerWidth - 50, nx));
                ny = Math.max(0, Math.min(window.innerHeight - 50, ny));
                win.style.left = nx + 'px';
                win.style.top = ny + 'px';
            });

            document.addEventListener('mouseup', () => {
                if (dragging) {
                    dragging = false;
                    win.style.cursor = 'default';
                }
            });
        }

        makeDraggable(document.getElementById('files-window'));
        makeDraggable(document.getElementById('notepad-window'));

        // make sure windows have initial left/top if not set
        if (!filesWin.style.left) filesWin.style.left = '5%';
        if (!filesWin.style.top) filesWin.style.top = '6%';
        if (!notepadWin.style.left) notepadWin.style.left = '30%';
        if (!notepadWin.style.top) notepadWin.style.top = '10%';

        // start notepad
        initTabs();

        // double click on files also open notepad? not needed.

        // ensure windows not collapsed on open (min size)
        function ensureSize(win) {
            const w = parseInt(win.style.width);
            const h = parseInt(win.style.height);
            if (!w || w < 360) win.style.width = '520px';
            if (!h || h < 240) win.style.height = '380px';
        }
        ensureSize(filesWin);
        ensureSize(notepadWin);

        // extra: handle new-tab insertion after render
        // already done

        console.log('Desktop ready');
    })();
</script>
</body>
</html>
